"use strict";(()=>{document.documentElement.dataset.backrowExtension=chrome.runtime.getManifest().version;document.dispatchEvent(new CustomEvent("backrow:extension-ready"));document.addEventListener("backrow:join",s=>{let e=s.detail;if(typeof e=="string")try{let{roomId:t,keyText:n,url:o}=JSON.parse(e);if(typeof t!="string"||typeof n!="string"||typeof o!="string")return;let r={type:"join",roomId:t,keyText:n,url:o};chrome.runtime.sendMessage(r)}catch{}});})();
